catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    calculateMetroFare();
}


function calculateMetroFare() {

    var sourceValue = g_form.getValue('source_station');
    var destinationValue = g_form.getValue('destination_station');
    var passengerType = g_form.getValue('passenger_type');

    var numberOfTickets = parseInt(
        g_form.getValue('number_of_tickets'),
        10
    );

    // Required information is not available yet
    if (!sourceValue ||
        !destinationValue ||
        !passengerType ||
        isNaN(numberOfTickets)) {

        g_form.clearValue('fare_per_ticket');
        g_form.clearValue('total_fare');

        return;
    }

    // Get Source Station record
    g_form.getReference('source_station', function(sourceStation) {

        if (!sourceStation) {
            g_form.clearValue('fare_per_ticket');
            g_form.clearValue('total_fare');
            return;
        }

        var sourceDistance = parseFloat(
            sourceStation.getValue('distance_from_origin')
        );

        // Get Destination Station record
        g_form.getReference(
            'destination_station',
            function(destinationStation) {

                if (!destinationStation) {
                    g_form.clearValue('fare_per_ticket');
                    g_form.clearValue('total_fare');
                    return;
                }

                var destinationDistance = parseFloat(
                    destinationStation.getValue('distance_from_origin')
                );

                // Check that both distances are valid
                if (isNaN(sourceDistance) ||
                    isNaN(destinationDistance)) {

                    g_form.clearValue('fare_per_ticket');
                    g_form.clearValue('total_fare');

                    return;
                }

                // Calculate journey distance
                var journeyDistance = Math.abs(
                    destinationDistance - sourceDistance
                );

                // Base fare
                // ₹10 base + ₹2 per kilometer
                var baseFare =
                    10 + (journeyDistance * 2);

                var farePerTicket = baseFare;

                // Apply passenger type discount
                if (passengerType == 'adult') {

                    // Adult: 100%
                    farePerTicket = baseFare;

                } else if (passengerType == 'child') {

                    // Child: 50%
                    farePerTicket = baseFare * 0.50;

                } else if (passengerType == 'senior_citizenth') {

                    // Senior Citizen: 70%
                    farePerTicket = baseFare * 0.70;
                }

                // Make sure ticket count is valid
                if (numberOfTickets < 1) {
                    numberOfTickets = 1;
                }

                // Calculate total fare
                var totalFare =
                    farePerTicket * numberOfTickets;

                // Populate Fare Per Ticket
                g_form.setValue(
                    'fare_per_ticket',
                    farePerTicket.toFixed(2)
                );

                // Populate Total Fare
                g_form.setValue(
                    'total_fare',
                    totalFare.toFixed(2)
                );
            }
        );
    });
}
